<?php
session_start(); require 'db.php';
if (!isset($_SESSION['role']) || $_SESSION['role'] !== 'faculty') { header('Location: index.php'); exit(); }
$faculty_id=(int)($_SESSION['user_id']??0); $name=$_SESSION['name']??'';
$conn->query("CREATE TABLE IF NOT EXISTS schedules (id INT AUTO_INCREMENT PRIMARY KEY, subject VARCHAR(100) NOT NULL, course VARCHAR(100) NOT NULL, section VARCHAR(50) NOT NULL, schedule_date DATE NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, room VARCHAR(50) NULL, faculty_id INT NULL, faculty VARCHAR(100) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$conn->query("ALTER TABLE schedules ADD COLUMN faculty_id INT NULL");
$stmt=$conn->prepare("SELECT subject,course,section,schedule_date,start_time,end_time,room FROM schedules WHERE faculty_id=? OR (faculty_id IS NULL AND faculty=?) ORDER BY schedule_date,start_time"); $stmt->bind_param('is',$faculty_id,$name); $stmt->execute(); $rows=$stmt->get_result();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Schedule - SAMS</title><link rel="stylesheet" href="faculty.css?v=3"></head><body><div class="header"><div class="header-title"><h2>ACLC College of Malolos - SAMS</h2><span>My complete teaching schedule</span></div><div class="header-user"><a href="faculty.php">Dashboard</a><a href="logout.php">Logout</a></div></div><main class="container"><h1>My Schedule</h1><div class="table-wrap"><table><thead><tr><th>Date</th><th>Time</th><th>Subject</th><th>Course</th><th>Section</th><th>Room</th></tr></thead><tbody><?php while($row=$rows->fetch_assoc()): ?><tr><td><?php echo htmlspecialchars($row['schedule_date']); ?></td><td><?php echo htmlspecialchars(substr($row['start_time'],0,5).' - '.substr($row['end_time'],0,5)); ?></td><td><?php echo htmlspecialchars($row['subject']); ?></td><td><?php echo htmlspecialchars($row['course']); ?></td><td><?php echo htmlspecialchars($row['section']); ?></td><td><?php echo htmlspecialchars($row['room']?:'—'); ?></td></tr><?php endwhile; ?></tbody></table></div></main></body></html>
